python3 -c "
import json,glob,collections
files=glob.glob('/home/lane/.claude/projects/**/*.jsonl',recursive=True)
fable=[]
allmodels=collections.Counter()
for f in files:
    ms=set()
    try:
        for l in open(f):
            try:o=json.loads(l)
            except:continue
            m=o.get('message')
            if isinstance(m,dict) and m.get('model'):
                ms.add(m['model']); allmodels[m['model']]+=1
    except:continue
    if any('fable' in x.lower() for x in ms):
        fable.append((f,ms))
print('ALL MODELS:',dict(allmodels))
print('FABLE FILES:',len(fable))
for f,ms in fable: print(f, ms)
"

